// ── Content ingester (architecture §4, build-time Model A) ───────────────
// Pure parser: reads the courses/ tree at startup, validates shape, builds
// an in-memory manifest. No toolchain, no network, no Judge0.
//
// Validation philosophy (§5):
//   - Fail loudly on structural violations (missing files, bad yaml).
//   - Trust expected.json values — they were generated by the oracle CLI
//     and are defended by the CI drift-guard job.
//   - Pass through unknown fields rather than reject them (future schema growth).

using System.Text.Json;
using YamlDotNet.Serialization;
using YamlDotNet.Serialization.NamingConventions;

namespace Backend.Content;

public class ContentIngester
{
    private readonly ILogger<ContentIngester> _log;
    private readonly string _coursesRoot;
    private readonly IDeserializer _yaml;

    // In-memory store keyed by course ID
    private readonly Dictionary<string, CourseManifest> _courses = new();

    public ContentIngester(ILogger<ContentIngester> log, IConfiguration config)
    {
        _log = log;

        // Resolve courses root relative to the content root (repo root in dev).
        // In production this will be an absolute path set via config.
        var root = config["ContentRoot"]
            ?? Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "courses");
        _coursesRoot = Path.GetFullPath(root);

        _yaml = new DeserializerBuilder()
            .WithNamingConvention(UnderscoredNamingConvention.Instance)
            .IgnoreUnmatchedProperties()   // forward-compatible: unknown fields pass through
            .Build();
    }

    // ── Public API ────────────────────────────────────────────────────────

    public IReadOnlyList<CourseManifest> AllCourses =>
        _courses.Values.ToList().AsReadOnly();

    public CourseManifest? GetCourse(string id) =>
        _courses.GetValueOrDefault(id);

    public SectionManifest? GetSection(string courseId, string sectionId)
    {
        if (!_courses.TryGetValue(courseId, out var course)) return null;
        return course.Chapters
            .SelectMany(ch => ch.Sections)
            .FirstOrDefault(s => s.Id == $"{courseId}/{sectionId}");
    }

    public ProblemManifest? GetProblem(string courseId, string sectionId, string problemId)
    {
        var section = GetSection(courseId, sectionId);
        return section?.Problems.FirstOrDefault(p => p.Id == $"{courseId}/{sectionId}/{problemId}");
    }

    // ── Ingest ────────────────────────────────────────────────────────────

    public void IngestAll()
    {
        if (!Directory.Exists(_coursesRoot))
        {
            _log.LogWarning("Courses root not found at {Path} — no content loaded", _coursesRoot);
            return;
        }

        var courseYamls = Directory.GetFiles(_coursesRoot, "course.yaml", SearchOption.AllDirectories);
        if (courseYamls.Length == 0)
        {
            _log.LogWarning("No course.yaml files found under {Path}", _coursesRoot);
            return;
        }

        foreach (var courseYamlPath in courseYamls)
        {
            try
            {
                var course = IngestCourse(Path.GetDirectoryName(courseYamlPath)!);
                _courses[course.Id] = course;
                var sectionCount = course.Chapters.Sum(ch => ch.Sections.Count);
                var problemCount = course.Chapters
                    .SelectMany(ch => ch.Sections)
                    .Sum(s => s.Problems.Count);
                _log.LogInformation(
                    "Ingested course {Id}: {Chapters} chapters, {Sections} sections, {Problems} problems",
                    course.Id, course.Chapters.Count, sectionCount, problemCount);
            }
            catch (Exception ex)
            {
                // A malformed course fails loudly — better to know at startup than
                // to serve partial content to a student.
                _log.LogError(ex, "Failed to ingest course at {Path}", courseYamlPath);
                throw;
            }
        }
    }

    // ── Course ────────────────────────────────────────────────────────────

    private CourseManifest IngestCourse(string courseDir)
    {
        var raw = ReadYaml<CourseYaml>(Path.Combine(courseDir, "course.yaml"));

        Require(raw.Id != null,    courseDir, "course.yaml missing 'id'");
        Require(raw.Title != null, courseDir, "course.yaml missing 'title'");
        Require(raw.Status != null, courseDir, "course.yaml missing 'status'");

        var sectionsRoot = Path.Combine(courseDir, "sections");
        if (!Directory.Exists(sectionsRoot))
            throw new InvalidOperationException($"{courseDir}: no sections/ directory");

        // Build a chapter number → ChapterYaml lookup from course.yaml
        var chapterMeta = raw.Chapters ?? [];

        // Discover all section folders, group by chapter number extracted from slug
        var sectionDirs = Directory.GetDirectories(sectionsRoot)
            .OrderBy(d => d)
            .ToList();

        // Separate regular sections from chapter tests
        var regularSections = sectionDirs.Where(d => !IsTestFolder(d)).ToList();
        var testFolders     = sectionDirs.Where(d => IsTestFolder(d)).ToDictionary(
            d => ExtractChapterNumber(Path.GetFileName(d)), d => d);

        // Group sections by chapter
        var sectionsByChapter = regularSections
            .GroupBy(d => ExtractChapterNumber(Path.GetFileName(d)))
            .ToDictionary(g => g.Key, g => g.OrderBy(d => d).ToList());

        var chapters = new List<ChapterManifest>();
        var allChapterNumbers = sectionsByChapter.Keys.Union(testFolders.Keys).OrderBy(n => n);

        foreach (var chNum in allChapterNumbers)
        {
            var meta = chapterMeta.FirstOrDefault(c => c.Number == chNum);
            var sections = sectionsByChapter.TryGetValue(chNum, out var dirs)
                ? dirs.Select(d => IngestSection(d, raw.Id!)).ToList()
                : new List<SectionManifest>();

            ChapterTestManifest? test = null;
            if (testFolders.TryGetValue(chNum, out var testDir))
            {
                try { test = IngestChapterTest(testDir, raw.Id!); }
                catch (Exception ex)
                {
                    _log.LogWarning(ex, "Skipping chapter test at {Dir} (not fully authored yet)", testDir);
                }
            }

            chapters.Add(new ChapterManifest(
                Number:      chNum,
                Title:       meta?.Title ?? $"Chapter {chNum}",
                RegionTitle: meta?.RegionTitle ?? $"Chapter {chNum}",
                Province:    meta?.Province ?? "",
                Sections:    sections.AsReadOnly(),
                Test:        test
            ));
        }

        return new CourseManifest(
            Id:       raw.Id!,
            Title:    raw.Title!,
            Status:   raw.Status!,
            Country:  raw.Country ?? "unknown",
            Chapters: chapters.AsReadOnly()
        );
    }

    // ── Section ───────────────────────────────────────────────────────────

    private SectionManifest IngestSection(string sectionDir, string courseId)
    {
        var slug = Path.GetFileName(sectionDir);
        var sectionId = $"{courseId}/{slug}";

        // section.yaml (required)
        var sectionYamlPath = Path.Combine(sectionDir, "section.yaml");
        SectionYaml? meta = null;
        if (File.Exists(sectionYamlPath))
            meta = ReadYaml<SectionYaml>(sectionYamlPath);

        // reading.md (required for published sections — warn if missing)
        var readingPath = Path.Combine(sectionDir, "reading.md");
        var reading = File.Exists(readingPath)
            ? File.ReadAllText(readingPath)
            : "";

        // cheatsheet.md (optional)
        var cheatPath = Path.Combine(sectionDir, "cheatsheet.md");
        var cheatsheet = File.Exists(cheatPath)
            ? File.ReadAllText(cheatPath)
            : "";

        // quiz.yaml (optional — test sections don't have one)
        var quizPath = Path.Combine(sectionDir, "quiz.yaml");
        QuizManifest quiz = new(sectionId, 0, false, Array.Empty<QuizQuestionManifest>());
        if (File.Exists(quizPath))
            quiz = IngestQuiz(quizPath, sectionId);

        // problems/
        var problemsDir = Path.Combine(sectionDir, "problems");
        var problems = Directory.Exists(problemsDir)
            ? Directory.GetDirectories(problemsDir)
                .OrderBy(d => d)
                .Select(d => IngestProblem(d, sectionId, courseId))
                .ToList()
                .AsReadOnly()
            : (IReadOnlyList<ProblemManifest>)Array.Empty<ProblemManifest>();

        return new SectionManifest(
            Id:                 sectionId,
            Number:             meta?.Number ?? ExtractSectionNumber(slug),
            Title:              meta?.Title  ?? SlugToTitle(slug),
            Subtitle:           meta?.Subtitle ?? "",
            LightsAt:           meta?.LightsAt ?? (int)Math.Ceiling(problems.Count * 0.6),
            MapName:            meta?.MapName ?? slug,
            ReadingMarkdown:    reading,
            CheatsheetMarkdown: cheatsheet,
            Quiz:               quiz,
            Problems:           problems
        );
    }

    // ── Problem ───────────────────────────────────────────────────────────

    private ProblemManifest IngestProblem(string problemDir, string sectionId, string courseId)
    {
        var slug = Path.GetFileName(problemDir);
        var problemId = $"{sectionId}/{slug}";

        // problem.yaml
        var yamlPath = Path.Combine(problemDir, "problem.yaml");
        Require(File.Exists(yamlPath), problemDir, "missing problem.yaml");
        var spec = ReadYaml<ProblemYaml>(yamlPath);

        Require(spec.Id != null,                   problemDir, "problem.yaml missing 'id'");
        Require(spec.Title != null,                problemDir, "problem.yaml missing 'title'");
        Require(spec.Grading != null,              problemDir, "problem.yaml missing 'grading'");
        Require(spec.Languages?.Count > 0,         problemDir, "problem.yaml missing 'languages'");
        Require(spec.Cases?.Count > 0,             problemDir, "problem.yaml 'cases' is empty");

        // Oracle rule: no case may carry an 'expected' value in problem.yaml
        // (problem.yaml uses dynamic objects via YAML deserialisation, so we
        //  read the raw YAML text to check for the 'expected' key)
        var rawYaml = File.ReadAllText(yamlPath);
        if (rawYaml.Contains("expected:"))
            throw new InvalidOperationException(
                $"{yamlPath}: a case contains 'expected'. Expecteds are generated by " +
                "the oracle CLI, never hand-typed. Remove it and run `node kh.mjs gen`.");

        // expected.json (required — must have been generated by kh.mjs)
        var expectedPath = Path.Combine(problemDir, "expected.json");
        Require(File.Exists(expectedPath), problemDir,
            "missing expected.json — run `node kh.mjs gen` in authoring/");
        var expectedDoc = JsonSerializer.Deserialize<ExpectedJson>(
            File.ReadAllText(expectedPath),
            new JsonSerializerOptions { PropertyNameCaseInsensitive = true })!;

        Require(expectedDoc.Cases?.Count == spec.Cases!.Count, problemDir,
            $"expected.json has {expectedDoc.Cases?.Count} cases but problem.yaml has {spec.Cases!.Count}");

        // Starter files (read contents for the Monaco workspace)
        var starterFiles = new Dictionary<string, IReadOnlyList<CodeFileManifest>>();
        foreach (var lang in spec.Languages!)
        {
            var filenames = spec.Starter?.GetValueOrDefault(lang) ?? [];
            var files = filenames.Select(fn =>
            {
                var fp = Path.Combine(problemDir, fn);
                Require(File.Exists(fp), problemDir, $"starter file not found: {fn}");
                return new CodeFileManifest(fn, File.ReadAllText(fp));
            }).ToList();
            starterFiles[lang] = files.AsReadOnly();
        }

        // design.md → student-facing statement
        var designPath = Path.Combine(problemDir, "design.md");
        var statement = File.Exists(designPath)
            ? File.ReadAllText(designPath)
            : spec.Title ?? slug;

        // Merge problem.yaml cases with expected.json outputs
        var cases = spec.Cases!.Zip(expectedDoc.Cases!, (c, e) =>
            new TestCaseManifest(
                Stdin:    c.Stdin ?? "",
                Expected: e.Expected ?? "",
                Note:     c.Note ?? ""))
            .ToList()
            .AsReadOnly();

        return new ProblemManifest(
            Id:               problemId,
            Title:            spec.Title!,
            Difficulty:       spec.Difficulty,
            Grading:          spec.Grading!,
            Languages:        spec.Languages!.AsReadOnly(),
            StarterFiles:     starterFiles,
            StatementMarkdown: statement,
            Cases:            cases
        );
    }

    // ── Quiz ──────────────────────────────────────────────────────────────

    private QuizManifest IngestQuiz(string quizPath, string sectionId)
    {
        var raw = ReadYaml<QuizYaml>(quizPath);
        var questions = (raw.Questions ?? [])
            .Select(q => new QuizQuestionManifest(
                Id:        q.Id ?? "",
                Type:      q.Type ?? "mcq",
                Prompt:    q.Prompt ?? "",
                Options:   q.Options?.Select(o => new McqOption(o.Id ?? "", o.Text ?? "")).ToList(),
                Answer:    NormaliseAnswer(q.Answer),
                Accept:    q.Accept,
                Rationale: q.Rationale ?? ""))
            .ToList()
            .AsReadOnly();

        return new QuizManifest(
            SectionId: raw.Section ?? sectionId,
            Pass:      raw.Pass,
            Shuffle:   raw.Shuffle,
            Questions: questions);
    }

    // ── Chapter test ──────────────────────────────────────────────────────

    private ChapterTestManifest IngestChapterTest(string testDir, string courseId)
    {
        var testYamlPath = Path.Combine(testDir, "test.yaml");
        Require(File.Exists(testYamlPath), testDir, "chapter test folder missing test.yaml");

        var raw = ReadYaml<TestYaml>(testYamlPath);
        Require(raw.Id != null, testDir, "test.yaml missing 'id'");

        // Pool problems
        var poolDir = Path.Combine(testDir, "pool");
        var pool = new List<ProblemManifest>();
        if (Directory.Exists(poolDir))
        {
            foreach (var problemSlug in raw.Pool ?? [])
            {
                var dir = Path.Combine(poolDir, problemSlug);
                if (!Directory.Exists(dir))
                {
                    _log.LogWarning("Chapter test pool references '{Slug}' but folder not found", problemSlug);
                    continue;
                }
                try
                {
                    pool.Add(IngestProblem(dir, raw.Id!, courseId));
                }
                catch (Exception ex)
                {
                    _log.LogWarning(ex, "Skipping pool problem {Slug} (not fully authored)", problemSlug);
                }
            }
        }

        // Cheatsheets
        var cheatsheetsDir = Path.Combine(testDir, "cheatsheets");
        var cheatsheets = new List<string>();
        if (Directory.Exists(cheatsheetsDir))
        {
            foreach (var f in Directory.GetFiles(cheatsheetsDir, "*.md").OrderBy(f => f))
                cheatsheets.Add(File.ReadAllText(f));
        }

        return new ChapterTestManifest(
            Id:                   raw.Id!,
            Kind:                 raw.Kind ?? "chapter-test",
            Title:                raw.Title ?? "Chapter Test",
            Draw:                 raw.Draw,
            LightAt:              raw.LightAt,
            WindowHours:          raw.WindowHours,
            Shuffle:              raw.Shuffle,
            PoolIds:              (raw.Pool ?? []).ToList().AsReadOnly(),
            Pool:                 pool.AsReadOnly(),
            CheatsheetMarkdowns:  cheatsheets.AsReadOnly()
        );
    }

    // ── Helpers ───────────────────────────────────────────────────────────

    private T ReadYaml<T>(string path) where T : new()
    {
        var text = File.ReadAllText(path);
        return _yaml.Deserialize<T>(text) ?? new T();
    }

    private static void Require(bool condition, string location, string message)
    {
        if (!condition)
            throw new InvalidOperationException($"Ingest error at {location}: {message}");
    }

    private static bool IsTestFolder(string dir)
    {
        var name = Path.GetFileName(dir);
        return name.Contains(".T-") || name.Contains(".E-");
    }

    private static int ExtractChapterNumber(string slug)
    {
        // "1.3-number-variables" → 1
        // "1.T-chapter-test"     → 1
        var dot = slug.IndexOf('.');
        if (dot > 0 && int.TryParse(slug[..dot], out var n)) return n;
        return 0;
    }

    /// <summary>
    /// "1.3-number-variables" → "1.3"
    /// "1.T-chapter-test"     → "1.T"
    /// </summary>
    private static string ExtractSectionNumber(string slug)
    {
        // slug format: "X.Y-rest-of-title"  or  "X.T-rest"
        var dash = slug.IndexOf('-');
        return dash > 0 ? slug[..dash] : slug;
    }

    /// <summary>
    /// "2.1-reading-input"             → "Reading input"
    /// "1.3-number-variables"          → "Number variables"
    /// "1.T-chapter-test"              → "Chapter test"
    /// </summary>
    private static string SlugToTitle(string slug)
    {
        // Drop the "X.Y-" or "X.T-" prefix, convert hyphens to spaces, title-case first word
        var dash = slug.IndexOf('-');
        if (dash < 0) return slug;
        var rest = slug[(dash + 1)..].Replace('-', ' ');
        if (rest.Length == 0) return slug;
        return char.ToUpperInvariant(rest[0]) + rest[1..];
    }

    private static string NormaliseAnswer(object? raw)
    {
        if (raw is null) return "";
        return raw switch
        {
            bool b   => b ? "true" : "false",
            string s => s,
            _        => raw.ToString() ?? ""
        };
    }

    // ── YAML DTO types (private — only used during ingestion) ─────────────

    private class CourseYaml
    {
        public string? Id { get; set; }
        public string? Title { get; set; }
        public string? Status { get; set; }
        public string? Country { get; set; }
        public List<ChapterYaml>? Chapters { get; set; }
    }

    private class ChapterYaml
    {
        public int    Number      { get; set; }
        public string? Title      { get; set; }
        public string? RegionTitle { get; set; }
        public string? Province   { get; set; }
    }

    private class SectionYaml
    {
        public string? Id       { get; set; }
        public string? Number   { get; set; }
        public string? Title    { get; set; }
        public string? Subtitle { get; set; }
        public int     LightsAt { get; set; }
        public string? MapName  { get; set; }
        public int     Chapter  { get; set; }
    }

    private class ProblemYaml
    {
        public string? Id         { get; set; }
        public string? Title      { get; set; }
        public int     Difficulty { get; set; }
        public string? Grading    { get; set; }
        public List<string>? Languages { get; set; }
        public Dictionary<string, List<string>>? Starter  { get; set; }
        public Dictionary<string, List<string>>? Solution { get; set; }
        public List<CaseYaml>? Cases { get; set; }
    }

    private class CaseYaml
    {
        public string? Stdin { get; set; }
        public string? Note  { get; set; }
    }

    private class QuizYaml
    {
        public string? Section   { get; set; }
        public int     Pass      { get; set; }
        public bool    Shuffle   { get; set; }
        public List<QuizQuestionYaml>? Questions { get; set; }
    }

    private class QuizQuestionYaml
    {
        public string? Id        { get; set; }
        public string? Type      { get; set; }
        public string? Prompt    { get; set; }
        public List<McqOptionYaml>? Options { get; set; }
        public object? Answer    { get; set; }
        public List<string>? Accept { get; set; }
        public string? Rationale { get; set; }
    }

    private class McqOptionYaml
    {
        public string? Id   { get; set; }
        public string? Text { get; set; }
    }

    private class TestYaml
    {
        public string? Id          { get; set; }
        public string? Kind        { get; set; }
        public string? Title       { get; set; }
        public int     Draw        { get; set; }
        public int     LightAt     { get; set; }
        public int     WindowHours { get; set; }
        public bool    Shuffle     { get; set; }
        public List<string>? Pool  { get; set; }
    }

    // ── expected.json DTO ─────────────────────────────────────────────────

    private class ExpectedJson
    {
        public List<ExpectedCase>? Cases { get; set; }
    }

    private class ExpectedCase
    {
        public string? Stdin    { get; set; }
        public string? Expected { get; set; }
        public string? Note     { get; set; }
    }
}
